t 1
gate loops
task linear_search(s: seq, x: int) returns (r: int)
  ensures r == -1 or r >= 0 and r < len(s) and s[r] == x
  ensures r == -1 ==> (forall i in [0, len(s)) . s[i] != x)
  ensures r != -1 ==> (forall i in [0, r) . i < len(s) ==> s[i] != x)
{
  r := -1;
  var i: int := 0;
  while i < len(s) and r == -1
    invariant r == -1 ==> (forall j in [0, i) . j < len(s) ==> s[j] != x)
    invariant r != -1 ==> r >= 0 and r < len(s) and s[r] == x and (forall j in [0, r) . j < len(s) ==> s[j] != x)
    invariant i >= 0 and i <= len(s)
    decreases len(s) - i
  {
    if s[i] == x {
      r := i;
    } else {
    }
    i := i + 1;
  }
}
```

```t
t 1
gate recursion
task gcd(a: int, b: int) returns (r: int)
  requires a >= 0
  requires b >= 0
  ensures r == gcds(a, b)
  decreases a + b
spec fun gcds(a: int, b: int): int
  decreases a + b
= if a <= 0 then b else if b <= 0 then a else if a > b then gcds(a - b, b) else if b > a then gcds(a, b - a) else a
{
  if a == 0 {
    r := b;
  } else {
    if b == 0 {
      r := a;
    } else {
      if a > b {
        r := gcd(a - b, b);
      } else {
        if b > a {
          r := gcd(a, b - a);
        } else {
          r := a;
        }
      }
    }
  }
}
```

```t
t 1
gate quantifiers
task greet(name: seq) returns (r: seq)
  ensures len(r) == len(name) + 7
  ensures r[0..7] == "Hello, "
  ensures r[7..len(r)] == name
{
  r := "Hello, " + name;
}
```

```t
t 1
gate loops
task extract_digits(s: seq) returns (r: seq)
  ensures len(r) <= len(s)
  ensures forall k in [0, len(r)) . r[k] >= '0' and r[k] <= '9'
{
  r := [];
  var i: int := 0;
  while i < len(s)
    invariant 0 <= i
    invariant i <= len(s)
    invariant len(r) <= i
    invariant forall k in [0, len(r)) . r[k] >= '0' and r[k] <= '9'
    decreases len(s) - i
  {
    if s[i] >= '0' and s[i] <= '9' {
      r := r + [s[i]];
    } else {
    }
    i := i + 1;
  }
}
```

```t
t 1
task word_count(s: seq) returns (r: int)
  ensures r == len(s.split())
{
  var t2: seq := s[0..len(s)];
  r := len(t2.split());
}
```

```t
t 1
task split_join(s: seq, c: int) returns (r: seq)
  ensures r == s
  ensures [c].join(s.split(c)) == s
{
  var trimmed: seq := s.strip();
  var rebuilt: seq := [c].join(s.split(c));
  r := rebuilt;
}
```

